const CONSTRAINT_FORMATTERS: Record<string, (params: object) => string> = {
  required: () => 'missing required property',
  type: params => `must be ${'type' in params ? String(params.type) : 'expected type'}`,
  enum: () => 'must be one of the allowed enum values',
};

function describeConstraint(keyword: string, params: object): string {
  const formatter = CONSTRAINT_FORMATTERS[keyword];
  return formatter ? formatter(params) : `failed ${keyword} constraint`;
}

function formatJsonPointer(pointer: string): string {
  if (!pointer) return '';
  const trimmed = pointer.startsWith('/') ? pointer.slice(1) : pointer;
  const segments = trimmed.split('/');
  return segments.map(decodeJsonPointerSegment).join('.');
}

function decodeJsonPointerSegment(segment: string): string {
  const withSlashes = segment.replace(/~1/g, '/');
  return withSlashes.replace(/~0/g, '~');
}

function joinFieldPath(basePath: string, propertyName: string): string {
  return basePath ? `${basePath}.${propertyName}` : propertyName;
}

