function readRecordField(candidate: unknown, key: string): string | undefined {
  if (!isPlainRecord(candidate)) return undefined;
  const fieldValue = candidate[key];
  return fieldValue === undefined ? undefined : String(fieldValue);
}

function isPlainRecord(candidate: unknown): candidate is Record<string, unknown> {
  return typeof candidate === 'object' && candidate !== null;
}

